    changed=[]
    for e in ENTRIES:
        p=root/e['path']; b=p.read_bytes(); got=hashlib.sha256(b).hexdigest()
        if got != e['base_sha256']: raise RuntimeError(f"base drift for {e['path']}: {got}")
        s=b.decode(); ns,n=PAT.subn(lambda m:f"{m.group(1)}{m.group(2)} {m.group(3)}(*a,**k):raise NotImplementedError",s)
